"use client"

import * as React from "react"
import { RotateCcw, Star, Trash2 } from "lucide-react"

import { agent as findAgent, maxRounds } from "@/lib/agents/registry"
import {
  addressOf,
  findAddress,
  isUnread,
  loadThreads,
  newThread,
  reply,
  running,
  saveThreads,
  when,
  type Folder,
  type Thread,
} from "@/lib/agents/inbox"
import { emptyRun, runAgent } from "@/lib/agents/run-client"
import { cn } from "@/lib/utils"
import { Prose, RunMeta, RunSteps } from "@/app/agents/transcript"
import { AppSidebar } from "@/registry/blocks/sidebar-09/components/app-sidebar"
import { Compose, type Draft } from "@/registry/blocks/sidebar-09/components/compose"
import { Button } from "@govblock/ui/components/nova/button"
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@govblock/ui/components/ny4/breadcrumb"
import { Separator } from "@govblock/ui/components/ny4/separator"
import {
  SidebarInset,
  SidebarProvider,
  SidebarTrigger,
} from "@govblock/ui/components/ny4/sidebar"

// The Agentic Inbox — shadcn's sidebar-09 mail block, repurposed.
//
// Live chat is what /agents already is. This is its long-form sibling, and it is
// mail all the way down because half a mail metaphor reads as a broken one: what
// you send is in Sent the moment you send it, the report arrives as an unread
// reply on the same thread, and stars, drafts and an undoable trash are what a
// reader already knows how to use.
//
// v1 runs the task in this tab. That is the honest shape for a public site with
// no accounts: threads are kept in this browser, and the surface says so rather
// than letting anyone assume a server is holding them. What makes it feel
// delivered anyway is Discord — the agent delivers the finished report into the
// channel under the same subject line, so it arrives somewhere that outlives the
// tab.

const EMPTY: Draft = { to: "", subject: "", body: "" }

export default function Page() {
  const [threads, setThreads] = React.useState<Thread[]>([])
  const [selected, setSelected] = React.useState<string | null>(null)
  const [folder, setFolder] = React.useState<Folder>("inbox")
  const [composing, setComposing] = React.useState(false)
  const [draft, setDraft] = React.useState<Draft>(EMPTY)
  const [draftId, setDraftId] = React.useState<string | null>(null)
  const [restored, setRestored] = React.useState(false)

  React.useEffect(() => {
    const stored = loadThreads()
    // A task that was running when the tab closed did not survive it. Say so
    // rather than leave a spinner that will never stop.
    const settled = stored.map((thread): Thread =>
      thread.status === "running"
        ? {
            ...thread,
            status: "failed",
            messages: thread.messages.map((message) =>
              message.from === "you"
                ? message
                : {
                    ...message,
                    body:
                      message.body +
                      (message.body ? "\n\n" : "") +
                      "This task was still running when the tab was closed, and tasks run in the tab. Send it again.",
                  }
            ),
          }
        : thread
    )
    setThreads(settled)
    setRestored(true)
  }, [])

  React.useEffect(() => {
    if (restored) saveThreads(threads)
  }, [threads, restored])

  const patch = React.useCallback((id: string, change: (thread: Thread) => Thread) => {
    setThreads((current) => current.map((thread) => (thread.id === id ? change(thread) : thread)))
  }, [])

  const send = React.useCallback(
    async (agentSlug: string, subject: string, body: string, existingId?: string) => {
      const definition = findAgent(agentSlug)
      if (!definition) return

      const thread = newThread({
        agent: definition.slug,
        agentName: definition.name,
        subject,
        body,
        status: "running",
      })
      // Sending a draft replaces it in place, so the thread keeps its position
      // rather than appearing twice.
      setThreads((current) => [
        thread,
        ...current.filter((entry) => entry.id !== existingId),
      ])
      setSelected(thread.id)
      setFolder("sent")
      setComposing(false)
      setDraft(EMPTY)
      setDraftId(null)

      // The reply exists from the first token, unread, so the thread reads as
      // an arriving message rather than appearing whole at the end.
      patch(thread.id, (current) => reply(current, emptyRun(), "running"))

      const finished = await runAgent({
        agent: definition.slug,
        maxRounds: maxRounds(definition),
        subject: thread.subject,
        turns: [{ role: "user", text: body }],
        onUpdate: (run) => patch(thread.id, (current) => reply(current, run, "running")),
      })

      patch(thread.id, (current) =>
        reply(current, finished, finished.failed ? "failed" : "delivered")
      )
      setFolder("inbox")
    },
    [patch]
  )

  const open = threads.find((thread) => thread.id === selected) ?? null

  // Opening a thread marks its reply read, the way opening a message does.
  React.useEffect(() => {
    if (!open || composing || !isUnread(open) || open.status === "running") return
    patch(open.id, (thread) => ({
      ...thread,
      messages: thread.messages.map((message) =>
        message.from === "you" ? message : { ...message, unread: false }
      ),
    }))
  }, [open, composing, patch])

  const startCompose = () => {
    setDraft(EMPTY)
    setDraftId(null)
    setComposing(true)
  }

  const saveDraft = () => {
    // An address resolves through findAddress, not by splitting the string:
    // the slug has hyphens ("bill-reader") and the address does not.
    const address = findAddress(draft.to)
    const thread = newThread({
      agent: address?.agent ?? draft.to,
      agentName: address?.name ?? (draft.to || "No recipient"),
      subject: draft.subject,
      body: draft.body,
      status: "draft",
    })
    setThreads((current) => [thread, ...current.filter((entry) => entry.id !== draftId)])
    setComposing(false)
    setFolder("drafts")
    setSelected(thread.id)
    setDraft(EMPTY)
    setDraftId(null)
  }

  const editDraft = (thread: Thread) => {
    const address = findAgent(thread.agent)
    setDraft({
      to: address ? addressOf(address).email : thread.agent,
      subject: thread.subject === "(no subject)" ? "" : thread.subject,
      body: thread.messages[0]?.body ?? "",
    })
    setDraftId(thread.id)
    setComposing(true)
  }

  const agentMessage = open?.messages.find((message) => message.from !== "you")

  return (
    <SidebarProvider style={{ "--sidebar-width": "350px" } as React.CSSProperties}>
      <AppSidebar
        threads={threads}
        selected={selected}
        folder={folder}
        onFolder={(next) => {
          setFolder(next)
          setComposing(false)
        }}
        onOpenThread={(id) => {
          setSelected(id)
          setComposing(false)
        }}
        onClear={() => {
          setThreads([])
          setSelected(null)
        }}
      />
      <SidebarInset>
        <header className="sticky top-0 flex shrink-0 items-center gap-2 border-b bg-background p-4">
          <SidebarTrigger className="-ml-1" />
          <Separator orientation="vertical" className="mr-2 data-[orientation=vertical]:h-4" />
          <Breadcrumb>
            <BreadcrumbList>
              <BreadcrumbItem className="hidden md:block">
                <BreadcrumbLink href="/agents">Agentic Inbox</BreadcrumbLink>
              </BreadcrumbItem>
              <BreadcrumbSeparator className="hidden md:block" />
              <BreadcrumbItem>
                <BreadcrumbPage>
                  {composing ? "New task" : (open?.subject ?? "Inbox")}
                </BreadcrumbPage>
              </BreadcrumbItem>
            </BreadcrumbList>
          </Breadcrumb>

          <div className="ml-auto flex items-center gap-1">
            {open && !composing && (
              <>
                <Button
                  variant="ghost"
                  size="sm"
                  aria-label={open.starred ? "Remove star" : "Star"}
                  onClick={() => patch(open.id, (t) => ({ ...t, starred: !t.starred }))}
                >
                  <Star className={cn("size-4", open.starred && "fill-current")} />
                </Button>
                <Button
                  variant="ghost"
                  size="sm"
                  aria-label={open.trashed ? "Restore" : "Move to trash"}
                  onClick={() => patch(open.id, (t) => ({ ...t, trashed: !t.trashed }))}
                >
                  {open.trashed ? <RotateCcw className="size-4" /> : <Trash2 className="size-4" />}
                </Button>
              </>
            )}
            <Button size="sm" onClick={startCompose} disabled={composing}>
              Compose
            </Button>
          </div>
        </header>

        <div className="flex flex-1 flex-col gap-4 p-4">
          {composing ? (
            <Compose
              draft={draft}
              onChange={setDraft}
              onSend={(address, current) =>
                void send(address.agent, current.subject, current.body, draftId ?? undefined)
              }
              onDiscard={() => {
                setComposing(false)
                setDraft(EMPTY)
                setDraftId(null)
              }}
              onSaveDraft={saveDraft}
            />
          ) : open ? (
            <article className="flex max-w-3xl flex-col gap-5">
              <header className="flex flex-col gap-1">
                <h1 className="text-lg font-semibold tracking-tight">{open.subject}</h1>
                <p className="text-sm text-muted-foreground">
                  To {open.agentName} · {when(open.createdAt)}
                  {open.trashed && " · in trash"}
                  {open.deliveredTo && ` · delivered to ${open.deliveredTo}`}
                </p>
              </header>

              <div className="rounded-lg border p-4 text-sm whitespace-pre-wrap">
                {open.messages[0]?.body}
              </div>

              {open.status === "draft" ? (
                <div>
                  <Button size="sm" onClick={() => editDraft(open)}>
                    Edit draft
                  </Button>
                </div>
              ) : (
                <section className="flex flex-col gap-4">
                  <div className="flex items-center gap-2 text-sm text-muted-foreground">
                    <span className="flex size-7 items-center justify-center rounded-full bg-muted text-xs font-medium">
                      {open.agentName
                        .split(/\s+/)
                        .map((word) => word[0])
                        .join("")
                        .slice(0, 2)
                        .toUpperCase()}
                    </span>
                    <span>{open.agentName}</span>
                    {agentMessage?.unread && (
                      <span className="rounded-full bg-primary/10 px-2 py-0.5 text-xs text-primary">
                        Unread
                      </span>
                    )}
                  </div>

                  {agentMessage?.body && (
                    <div
                      className={cn(
                        "text-sm whitespace-pre-wrap",
                        open.status === "failed" && "text-destructive"
                      )}
                    >
                      <Prose text={agentMessage.body} />
                    </div>
                  )}

                  {open.status === "running" && (
                    // The reading pane's own sign of life. It names the tool in
                    // flight rather than saying "working", so a long gather
                    // reads as progress instead of as a hang.
                    <div className="flex items-center gap-2 text-sm text-muted-foreground">
                      <span
                        aria-hidden
                        className="size-2 shrink-0 animate-pulse rounded-full bg-primary"
                      />
                      <span className="animate-pulse">{running(open)}</span>
                    </div>
                  )}

                  {(agentMessage?.run?.steps.length ?? 0) > 0 && (
                    <details className="rounded-lg border p-3">
                      <summary className="cursor-pointer text-sm text-muted-foreground">
                        {agentMessage!.run!.steps.length} tool call
                        {agentMessage!.run!.steps.length === 1 ? "" : "s"}
                        {open.status === "running" ? " so far" : ""}
                      </summary>
                      <div className="pt-3">
                        <RunSteps steps={agentMessage!.run!.steps} />
                      </div>
                    </details>
                  )}

                  {agentMessage?.run && <RunMeta run={agentMessage.run} />}
                </section>
              )}
            </article>
          ) : (
            <div className="flex max-w-3xl flex-col gap-3">
              <h1 className="text-lg font-semibold tracking-tight">Agentic Inbox</h1>
              <p className="text-sm text-muted-foreground">
                Longer work than a chat. Compose a task to one of the five agents, and its
                finished report arrives as a reply on the same thread, with the run it did
                underneath. The Researcher writes a sourced report over the record; the Tracker
                watches a topic and posts a digest; the other three answer in one message.
              </p>
              <p className="text-sm text-muted-foreground">
                This site is public and has no accounts, so threads are kept in this browser and
                nowhere else — nobody else can see them, and they do not follow you to another
                device. A task runs while this tab is open. What outlives the tab is the report
                the agent delivers to Discord, under the same subject line.
              </p>
              <div>
                <Button size="sm" onClick={startCompose}>
                  Compose
                </Button>
              </div>
            </div>
          )}
        </div>
      </SidebarInset>
    </SidebarProvider>
  )
}

"use client"

import * as React from "react"
import { Command, File, Inbox, Send, Star, Trash2 } from "lucide-react"

import {
  inFolder,
  isUnread,
  matches,
  running,
  teaser,
  unreadIn,
  when,
  type Folder,
  type Thread,
} from "@/lib/agents/inbox"
import { cn } from "@/lib/utils"
import { NavUser } from "@/registry/blocks/sidebar-09/components/nav-user"
import { Label } from "@govblock/ui/components/ny4/label"
import {
  Sidebar,
  SidebarContent,
  SidebarFooter,
  SidebarGroup,
  SidebarGroupContent,
  SidebarHeader,
  SidebarInput,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  useSidebar,
} from "@govblock/ui/components/ny4/sidebar"
import { Switch } from "@govblock/ui/components/ny4/switch"

// The Agentic Inbox. This is shadcn's sidebar-09 mail block with its markup and
// classNames intact and its contents replaced: the icon rail is the folders, the
// second sidebar is the thread list, and a thread is a task — the message you
// sent and the agent's reply to it. Repurposed by content; nothing redesigned.

const FOLDERS: { title: string; icon: typeof Inbox; folder: Folder }[] = [
  { title: "Inbox", icon: Inbox, folder: "inbox" },
  { title: "Sent", icon: Send, folder: "sent" },
  { title: "Drafts", icon: File, folder: "drafts" },
  { title: "Starred", icon: Star, folder: "starred" },
  { title: "Trash", icon: Trash2, folder: "trash" },
]

export function AppSidebar({
  threads,
  selected,
  folder,
  onFolder,
  // Not `onSelect`: Sidebar spreads a div's props, whose own onSelect would
  // intersect with this one and hand the callback a SyntheticEvent.
  onOpenThread,
  onClear,
  ...props
}: React.ComponentProps<typeof Sidebar> & {
  threads: Thread[]
  selected: string | null
  folder: Folder
  onFolder: (folder: Folder) => void
  onOpenThread: (id: string) => void
  onClear: () => void
}) {
  const [query, setQuery] = React.useState("")
  const [unreadOnly, setUnreadOnly] = React.useState(false)
  const { setOpen } = useSidebar()

  const active = FOLDERS.find((entry) => entry.folder === folder) ?? FOLDERS[0]!

  // Search reaches across every folder, the way mail search does — a thread you
  // sent and a report you were sent are the same thread, and looking for one
  // should not depend on remembering which side of it you are on.
  const searching = query.trim().length > 0
  const shown = threads
    .filter((thread) => (searching ? !thread.trashed || folder === "trash" : inFolder(thread, folder)))
    .filter((thread) => matches(thread, query))
    .filter((thread) => !unreadOnly || isUnread(thread))

  return (
    <Sidebar
      collapsible="icon"
      className="overflow-hidden *:data-[sidebar=sidebar]:flex-row"
      {...props}
    >
      {/* This is the first sidebar */}
      {/* We disable collapsible and adjust width to icon. */}
      {/* This will make the sidebar appear as icons. */}
      <Sidebar
        collapsible="none"
        className="w-[calc(var(--sidebar-width-icon)+1px)]! border-r"
      >
        <SidebarHeader>
          <SidebarMenu>
            <SidebarMenuItem>
              <SidebarMenuButton size="lg" asChild className="md:h-8 md:p-0">
                <a href="/agents">
                  <div className="flex aspect-square size-8 items-center justify-center rounded-lg bg-sidebar-primary text-sidebar-primary-foreground">
                    <Command className="size-4" />
                  </div>
                  <div className="grid flex-1 text-left text-sm leading-tight">
                    <span className="truncate font-medium">govblock</span>
                    <span className="truncate text-xs">Agentic Inbox</span>
                  </div>
                </a>
              </SidebarMenuButton>
            </SidebarMenuItem>
          </SidebarMenu>
        </SidebarHeader>
        <SidebarContent>
          <SidebarGroup>
            <SidebarGroupContent className="px-1.5 md:px-0">
              <SidebarMenu>
                {FOLDERS.map((item) => {
                  const unread = unreadIn(threads, item.folder)
                  return (
                    <SidebarMenuItem key={item.title}>
                      <SidebarMenuButton
                        tooltip={{
                          children: unread ? `${item.title} (${unread})` : item.title,
                          hidden: false,
                        }}
                        onClick={() => {
                          onFolder(item.folder)
                          setOpen(true)
                        }}
                        isActive={folder === item.folder}
                        className="px-2.5 md:px-2"
                      >
                        <item.icon />
                        <span>{item.title}</span>
                        {unread > 0 && (
                          <span className="ml-auto text-xs tabular-nums">{unread}</span>
                        )}
                      </SidebarMenuButton>
                    </SidebarMenuItem>
                  )
                })}
              </SidebarMenu>
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>
        <SidebarFooter>
          <NavUser
            user={{
              name: "This browser",
              email: `${threads.length} thread${threads.length === 1 ? "" : "s"} kept locally`,
              avatar: "",
            }}
            onClear={onClear}
          />
        </SidebarFooter>
      </Sidebar>

      {/* This is the second sidebar */}
      {/* We disable collapsible and let it fill remaining space */}
      <Sidebar collapsible="none" className="hidden flex-1 md:flex">
        <SidebarHeader className="gap-3.5 border-b p-4">
          <div className="flex w-full items-center justify-between">
            <div className="text-base font-medium text-foreground">
              {searching ? "All mail" : active.title}
            </div>
            <Label className="flex items-center gap-2 text-sm">
              <span>Unreads</span>
              <Switch
                className="shadow-none"
                checked={unreadOnly}
                onCheckedChange={(next: boolean) => setUnreadOnly(next)}
              />
            </Label>
          </div>
          <SidebarInput
            placeholder="Search mail…"
            value={query}
            onChange={(event) => setQuery(event.target.value)}
          />
        </SidebarHeader>
        <SidebarContent>
          <SidebarGroup className="px-0">
            <SidebarGroupContent>
              {shown.length === 0 && (
                <p className="p-4 text-sm text-muted-foreground">
                  {searching
                    ? `Nothing matches “${query.trim()}”.`
                    : folder === "inbox"
                      ? "Nothing has arrived yet. Compose a task and the reply lands here."
                      : "Nothing here."}
                </p>
              )}
              {shown.map((thread) => {
                const unread = isUnread(thread)
                return (
                  <button
                    type="button"
                    key={thread.id}
                    onClick={() => onOpenThread(thread.id)}
                    data-active={selected === thread.id}
                    className="flex w-full flex-col items-start gap-2 border-b p-4 text-left text-sm leading-tight whitespace-nowrap last:border-b-0 hover:bg-sidebar-accent hover:text-sidebar-accent-foreground data-[active=true]:bg-sidebar-accent data-[active=true]:text-sidebar-accent-foreground"
                  >
                    <div className="flex w-full items-center gap-2">
                      <span className={cn(unread && "font-semibold")}>{thread.agentName}</span>
                      {thread.starred && (
                        <Star className="size-3 fill-current text-muted-foreground" />
                      )}
                      <span className="ml-auto text-xs">{when(thread.updatedAt)}</span>
                    </div>
                    <span
                      className={cn("w-[260px] truncate", unread ? "font-semibold" : "font-medium")}
                    >
                      {thread.subject}
                    </span>
                    <span className="line-clamp-2 flex w-[260px] items-start gap-1.5 text-xs whitespace-break-spaces">
                      {thread.status === "running" && (
                        // A running task must never be mistaken for a finished
                        // one. The dot pulses beside whatever tool is in flight.
                        <span
                          aria-hidden
                          className="mt-1 size-1.5 shrink-0 animate-pulse rounded-full bg-primary"
                        />
                      )}
                      <span className={thread.status === "running" ? "animate-pulse" : undefined}>
                        {thread.status === "draft" && "Draft · "}
                        {thread.status === "failed" && "Failed · "}
                        {thread.status === "running" ? running(thread) : teaser(thread)}
                      </span>
                    </span>
                  </button>
                )
              })}
            </SidebarGroupContent>
          </SidebarGroup>
        </SidebarContent>
      </Sidebar>
    </Sidebar>
  )
}

"use client"

import * as React from "react"

import { ADDRESSES, matchAddresses, findAddress, type Address } from "@/lib/agents/inbox"
import { agent as findAgent } from "@/lib/agents/registry"
import { cn } from "@/lib/utils"
import { Button } from "@govblock/ui/components/nova/button"
import { Input } from "@govblock/ui/components/ny4/input"
import { Textarea } from "@govblock/ui/components/nova/textarea"

// Compose. The To: field is the agent picker, because "who do I send this to"
// is a question mail already answers well and a row of buttons is a worse
// version of it. Typing filters by name, address or speciality; the suggestion
// list carries the monogram and the one line that says what each one is for,
// which is the same copy /agents shows on its cards.

export type Draft = { to: string; subject: string; body: string }

export function Compose({
  draft,
  onChange,
  onSend,
  onDiscard,
  onSaveDraft,
}: {
  draft: Draft
  onChange: (draft: Draft) => void
  onSend: (address: Address, draft: Draft) => void
  onDiscard: () => void
  onSaveDraft: () => void
}) {
  const [picking, setPicking] = React.useState(false)
  const resolved = findAddress(draft.to)
  const suggestions = matchAddresses(draft.to).slice(0, 5)
  const definition = resolved ? findAgent(resolved.agent) : undefined

  const choose = (address: Address) => {
    onChange({ ...draft, to: address.email })
    setPicking(false)
  }

  return (
    <form
      className="flex max-w-3xl flex-col gap-3"
      onSubmit={(event) => {
        event.preventDefault()
        if (resolved) onSend(resolved, draft)
      }}
    >
      <div className="relative flex flex-col gap-1">
        <div className="flex items-center gap-3 border-b pb-2">
          <label
            htmlFor="task-recipient"
            className="w-16 shrink-0 text-sm text-muted-foreground"
          >
            To
          </label>
          {/*
            Chrome offers its own address autofill over ours — a "To" label and
            an @-shaped placeholder is enough for its heuristics to call this an
            email field, and the reader gets their personal gmail and "Manage
            Addresses…" on top of the agent list. autoComplete="off" alone does
            not stop it, so the field also carries no mail-ish token in its id or
            name, declares text rather than email, and says what it actually is:
            a combobox over a list this page owns. The placeholder shows a name
            rather than an address for the same reason; the dropdown rows still
            show the addresses, because that is where they belong.
          */}
          <Input
            id="task-recipient"
            name="task-recipient"
            type="text"
            role="combobox"
            aria-autocomplete="list"
            aria-expanded={picking && suggestions.length > 0}
            aria-controls="task-recipient-options"
            autoComplete="off"
            spellCheck={false}
            value={draft.to}
            onChange={(event) => {
              onChange({ ...draft, to: event.target.value })
              setPicking(true)
            }}
            onFocus={() => setPicking(true)}
            onBlur={() => window.setTimeout(() => setPicking(false), 150)}
            placeholder="Researcher"
            className="border-0 shadow-none focus-visible:ring-0"
          />
          {resolved && (
            <span className="shrink-0 text-xs text-muted-foreground">{resolved.name}</span>
          )}
        </div>

        {picking && suggestions.length > 0 && (
          <div
            id="task-recipient-options"
            role="listbox"
            className="absolute top-full right-0 left-16 z-20 mt-1 overflow-hidden rounded-lg border bg-popover shadow-md"
          >
            {suggestions.map((address) => (
              <button
                key={address.email}
                type="button"
                role="option"
                aria-selected={resolved?.email === address.email}
                onMouseDown={(event) => event.preventDefault()}
                onClick={() => choose(address)}
                className={cn(
                  "flex w-full items-center gap-3 px-3 py-2 text-left hover:bg-muted",
                  resolved?.email === address.email && "bg-muted"
                )}
              >
                <span className="flex size-8 shrink-0 items-center justify-center rounded-full bg-muted text-xs font-medium">
                  {address.monogram}
                </span>
                <span className="flex min-w-0 flex-col">
                  <span className="text-sm">
                    {address.name}{" "}
                    <span className="text-muted-foreground">&lt;{address.email}&gt;</span>
                  </span>
                  <span className="truncate text-xs text-muted-foreground">
                    {address.speciality}
                  </span>
                </span>
              </button>
            ))}
          </div>
        )}
      </div>

      <div className="flex items-center gap-3 border-b pb-2">
        <label htmlFor="compose-subject" className="w-16 shrink-0 text-sm text-muted-foreground">
          Subject
        </label>
        <Input
          id="compose-subject"
          value={draft.subject}
          onChange={(event) => onChange({ ...draft, subject: event.target.value })}
          placeholder="What the report is about"
          className="border-0 shadow-none focus-visible:ring-0"
        />
      </div>

      <Textarea
        value={draft.body}
        onChange={(event) => onChange({ ...draft, body: event.target.value })}
        placeholder={definition?.placeholder ?? "What should it do?"}
        className="min-h-48"
      />

      {definition && (
        <div className="flex flex-wrap gap-2">
          {definition.starters.map((starter) => (
            <Button
              key={starter}
              type="button"
              variant="outline"
              size="sm"
              onClick={() =>
                onChange({ ...draft, body: starter, subject: draft.subject || starter })
              }
            >
              {starter}
            </Button>
          ))}
        </div>
      )}

      <div className="flex flex-wrap items-center gap-2">
        <Button type="submit" size="sm" disabled={!resolved || !draft.body.trim()}>
          Send
        </Button>
        <Button type="button" variant="outline" size="sm" onClick={onSaveDraft}>
          Save draft
        </Button>
        <Button type="button" variant="ghost" size="sm" onClick={onDiscard}>
          Discard
        </Button>
        <span className="ml-auto text-xs text-muted-foreground">
          {resolved
            ? "Runs in this tab. Kept in this browser, not on a server."
            : `Address one of: ${ADDRESSES.map((a) => a.email).join(", ")}`}
        </span>
      </div>
    </form>
  )
}
